$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;Import-Module (Join-Path $root 'scripts\LanSecurity.psm1') -Force
function Throws([scriptblock]$a,[string]$m){try{&$a;throw 'Expected failure'}catch{if($_.Exception.Message-notmatch[regex]::Escape($m)){throw}}}
foreach($a in @('10.1.2.3','172.31.2.3','192.168.20.4')){if(-not(Test-GbuzzPrivateIPv4 $a)){throw "Private rejected: $a"}};foreach($a in @('0.0.0.0','127.0.0.1','8.8.8.8')){if(Test-GbuzzPrivateIPv4 $a){throw "Unsafe accepted: $a"}};if(-not(Test-GbuzzAddressInCidr '192.168.20.4' '192.168.20.0/24')){throw 'Member rejected'};if(Test-GbuzzAddressInCidr '192.168.21.4' '192.168.20.0/24'){throw 'Outsider accepted'};Throws {Test-GbuzzAddressInCidr '192.168.1.2' '8.8.8.0/24'} 'RFC1918'
$base=Get-Content -Raw (Join-Path $root docker-compose.yml);if($base-notmatch'BUZZ_HTTP_BIND_ADDR:-127\.0\.0\.1'){throw 'Base bind not loopback'};$lan=Get-Content -Raw (Join-Path $root docker-compose.lan.yml);foreach($x in @('!override','BUZZ_LAN_BIND_ADDR:?set')){if($lan-notmatch[regex]::Escape($x)){throw "LAN overlay missing $x"}};$acl=Get-Content -Raw (Join-Path $root 'scripts\protect-gbuzz-secrets.ps1');foreach($x in @('SetAccessRuleProtection($true,$false)','RollbackManifest','transaction rolled back','deny_aces','overlapping_allow_identities')){if($acl-notmatch[regex]::Escape($x)){throw "ACL control missing $x"}};$fw=Get-Content -Raw (Join-Path $root 'scripts\configure-gbuzz-lan-boundary.ps1');foreach($x in @('OwnerApprovedCidr','Overlapping inbound allows')){if($fw-notmatch[regex]::Escape($x)){throw "Firewall control missing $x"}}
$scratch=Join-Path ([IO.Path]::GetTempPath()) ('gbuzz-evidence-'+[guid]::NewGuid().ToString('n'));New-Item -ItemType Directory $scratch|Out-Null;try{$digest='a'*64;$image="registry/gbuzz@sha256:$digest";$commit=git -C $root rev-parse HEAD;@{services=@{relay=@{image=$image}}}|ConvertTo-Json -Depth 4|Set-Content "$scratch/compose.json";Set-Content "$scratch/images.txt" $image;Set-Content "$scratch/sbom.json" '{}';@{runs=@(@{results=@()})}|ConvertTo-Json -Depth 5|Set-Content "$scratch/vuln.sarif";@(@{image=$image;verified=$true;identity='builder';issuer='oidc'})|ConvertTo-Json|Set-Content "$scratch/signatures.json";@(@{image=$image;verified=$true;builder_id='gha';source_commit=$commit})|ConvertTo-Json|Set-Content "$scratch/provenance.json";& (Join-Path $root 'scripts\new-release-security-evidence.ps1') -ResolvedComposeJson "$scratch/compose.json" -BuildImageManifest "$scratch/images.txt" -SbomPath "$scratch/sbom.json" -VulnerabilitySarif "$scratch/vuln.sarif" -SignatureReport "$scratch/signatures.json" -ProvenanceReport "$scratch/provenance.json" -OutputPath "$scratch/evidence.json"|Out-Null;if(-not(Test-Path "$scratch/evidence.json")){throw 'Evidence output missing'};@{runs=@(@{results=@(@{ruleId='CVE-test'})})}|ConvertTo-Json -Depth 5|Set-Content "$scratch/vuln.sarif";Throws {& (Join-Path $root 'scripts\new-release-security-evidence.ps1') -ResolvedComposeJson "$scratch/compose.json" -BuildImageManifest "$scratch/images.txt" -SbomPath "$scratch/sbom.json" -VulnerabilitySarif "$scratch/vuln.sarif" -SignatureReport "$scratch/signatures.json" -ProvenanceReport "$scratch/provenance.json" -OutputPath "$scratch/bad.json"} 'Vulnerability gate failed'}finally{Remove-Item $scratch -Recurse -Force};Write-Output 'LAN security negative tests passed.'
